// CENSUS 1 data (status2 design): the hand-written census of the 73 kind-L status moves. census-moves-build.ts merges it
// with the generated facts (games from app/lib/battle/status-table.ts, learners and handler prints from
// census-moves-dex.out, pinned source ranges from census-moves-src.out) and writes census-moves.json and census-moves.md.
// Citations: PS/ = node_modules/.cache/champions/pokemon-showdown-c23d2e942c9c0daadb13a7162a385bf78e3c9353 (read-only);
// "Kn" = census-moves-probes.out probe Kn (this folder); "status-eot Qn/Pn" = status-eot/design/status-probes-*.out;
// "T9b" = status-eot/design/addendum-probes-2.out.

export type Risk = "low" | "medium" | "high";
export type Family =
  | "stages" | "stored-stats" | "types" | "abilities" | "items" | "cures" | "next-move" | "move-type" | "side" | "field" | "copy";

export type CensusRecord = {
  id: string;
  family: Family;
  /** What the move does in pinned Showdown (target, flags that matter, failure rules, effect), with the key citations. */
  behaviour: string;
  /** Differences between the games where the move exists (mods and generation branches); "" when none. */
  perGame: string;
  /** The state kinds the move writes. */
  changes: string[];
  /** What later in the same turn reads that state. */
  sameTurn: string;
  /** What the end of turn reads (doubles-eot.ts / residuals.ts) or does because of it. */
  endOfTurn: string;
  /** What it leaves for the next turn (E2 outcome, Training's carried state; public or not). */
  carried: string;
  /** What the engine already has that it can reuse (files and functions). */
  reuse: string;
  /** What the engine does not have yet. */
  needs: string;
  /** Inputs the calculator would need (state from before the turn), "" when none. */
  inputs: string;
  /** Random events the move adds and their exact weights; "none" when it adds none. */
  random: string;
  risk: Risk;
  riskWhy: string;
  /** Probe ids (census-moves-probes.out unless prefixed). */
  probes: string[];
};

